// Sun icon (clear sky)
export function SunIcon({ className = 'w-8 h-8', animate = true }: DoodleIconProps) {
  return (
    <motion.svg
      className={className}
      viewBox="0 0 100 100"
      fill="none"
      animate={animate ? { rotate: [0, 360] } : {}}
      transition={{ duration: 20, repeat: Infinity, ease: 'linear' }}
    >
      <circle
        cx="50"
        cy="50"
        r="22"
        fill="#EAC102"
        stroke="#1A1A1A"
        strokeWidth="3"
        strokeLinecap="round"
      />
      {[0, 45, 90, 135, 180, 225, 270, 315].map((angle) => {
        const rad = (angle * Math.PI) / 180;
        const x1 = 50 + Math.cos(rad) * 30;
        const y1 = 50 + Math.sin(rad) * 30;
        const x2 = 50 + Math.cos(rad) * 40;
        const y2 = 50 + Math.sin(rad) * 40;
        return (
          <line
            key={angle}
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            stroke="#EAC102"
            strokeWidth="4"
            strokeLinecap="round"
          />
        );
      })}
    </motion.svg>
  );
}

